const meta = {
  component: Toolbar,
  parameters: {
    docs: {
      description: {
        component: "## Usage

A labeled command bar with arrow-key navigation. `ToolbarButton` and `ToolbarLink` use the shared button styles; compose toggles or popup triggers with the button’s `render` prop. In a horizontal toolbar, put an input last so arrow keys still work for text editing.

**Import:** `@/registry/erbium/ui/toolbar`

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Toolbar](https://base-ui.com/react/components/toolbar)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Toolbar>;

export default { ...meta, title: "Components/Toolbar",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

