          <Icon name="bold" />
        </ToolbarButton>
        <ToolbarButton render={<Toggle aria-label="Italic" />} size="icon-sm">
          <Icon name="italic" />
        </ToolbarButton>
        <ToolbarButton render={<Toggle aria-label="Underline" />} size="icon-sm">
          <Icon name="underline" />
