      </ToolbarGroup>
      <ToolbarSeparator />
      <ToolbarButton aria-label="Insert link" size="icon-sm">
        <Icon name="link-01" />
      </ToolbarButton>
    </Toolbar>
  );
}
" },
    },
  },
  render: FormattingExample,
};

